package com.example.multimodal.controller;

import com.example.multimodal.service.MultimodalInferenceService;
import com.example.multimodal.service.MultimodalInput;
import com.example.multimodal.service.MultimodalResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/multimodal")
public class MultimodalController {

    private final MultimodalInferenceService inferenceService;

    public MultimodalController(MultimodalInferenceService inferenceService) {
        this.inferenceService = inferenceService;
    }

    @PostMapping("/infer")
    public ResponseEntity<MultimodalResponse> infer(@RequestBody MultimodalInput input) {
        try {
            MultimodalResponse response = inferenceService.infer(input);
            return ResponseEntity.ok(response);
        } catch (Exception e) {
            return ResponseEntity.status(HttpStatus.SERVICE_UNAVAILABLE)
                                 .body(new MultimodalResponse("Error processing request: " + e.getMessage(), 0));
        }
    }
}
```

